type
  Stack<T> = class
  private 
    fTop: SingleNode<T> := nil; 
  public 
    constructor Create;
    begin
      fTop := nil;
    end;

    procedure Push(x: T);
    begin
      fTop := new SingleNode<T>(x, fTop);
    end;

    function Pop: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to pop element from empty stack');

      Result := fTop.data;
      fTop := fTop.next;  
    end;

    function Top: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to get element from empty stack');

      Result := fTop.data;
    end;

    function IsEmpty: boolean;
    begin
      Result := (fTop = nil);
    end;

    function ToString: string; override;
    begin
      Result := '';
      var curElem := fTop;
      while curElem <> nil do
      begin
        Result += curElem.data.ToString + ' ';
        curElem := curElem.next;
      end;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  Queue<T> = class
  private 
    head: SingleNode<T>;
    tail: SingleNode<T>;
  public 
    constructor Create;
    begin
      head := nil;
      tail := nil;
    end;

    procedure Enqueue(x: T);
    begin
      if IsEmpty then
      begin
        head := new SingleNode<T>(x, nil);
        tail := head;
      end
      else
      begin
        tail.next := new SingleNode<T>(x, nil);
        tail := tail.next;
      end;
    end;

    function Dequeue: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to remove element from empty queue');

      Result := head.data;
      head := head.next;
      if head = nil then
        tail := nil;
    end;

    function Top: T;
    begin
      if IsEmpty then 
        raise new Exception('Attempt to get element from empty queue');
      Result := head.data;
    end;

    function IsEmpty: boolean;
    begin
      Result := (head = nil);
      if Result then
        Assert(tail = nil);
    end;

    function ToString: string; override;
    begin
      Result := '';
      var curElem := head;
      while curElem <> nil do
      begin
        Result += curElem.data + ' ';
        curElem := curElem.next;
      end;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  DynArray<T> = class
  private 
    fData: array of T;
    fSize: integer;
    fCap: integer;

    procedure SetElem(index: integer; x: T);
    begin
      if (index < 0) or (index > fSize - 1) then 
        raise new Exception('Attempt to set value to element outside array bounds with index ' + index.ToString);

      fData[index] := x;
    end;

    function GetElem(index: integer): T;
    begin
      if (index < 0) or (index > fSize - 1) then 
        raise new Exception('Attempt to get value from element outside array bounds with index ' + index.ToString);

      Result := fData[index];
    end;

  public 
    constructor Create;
    begin
      Create(0);
    end;

    constructor Create(pSize: integer);
    begin
      if pSize < 0 then
        raise new Exception('Attempt to set negative value to array size ' + pSize.ToString);

      fSize := pSize;
      fCap := 2 * pSize + 4;
      SetLength(fData, fCap);
    end;

    procedure Reserve(newCap: integer);
    begin
      if newCap > fCap then 
      begin
        SetLength(fData, newCap);
        fCap := newCap;
      end;
    end;

    procedure Resize(newSize: integer);
    begin
      if newSize < 0 then
        raise new Exception('Attempt to set negative value to array size ' + newSize.ToString);

      if newSize > fCap then
      begin
        Reserve(2 * newSize);
        for var i := fSize to newSize - 1 do
          fData[i] := default(T);
      end;
      fSize := newSize;
    end;

    procedure Add(x: T);
    begin
      Resize(fSize + 1);
      fData[fSize - 1] := x;
    end;

    procedure Insert(pos: integer; x: T);
    begin
      if (pos < 0) or (pos > fSize - 1) then 
        raise new Exception('Attempt to insert outside array bounds at position ' + pos.ToString);

      Resize(fSize + 1);
      for var i := fSize - 2 downto pos do
        fData[i + 1] := fData[i];
      fData[pos] := x;
    end;

    procedure Remove(pos: integer);
    begin
      if (pos < 0) or (pos > fSize - 1) then 
        raise new Exception('Attempt to remove outside array bounds from position ' + pos.ToString);

      for var i := pos to fSize - 2 do
        fData[i] := fData[i + 1];
      Resize(fSize - 1);
    end;

    function Find(x: T): integer;
    begin
      Result := -1;
      for var i := 0 to fSize - 1 do
        if fData[i] = x then
        begin
          Result := i;
          exit;
        end;
    end;

    property Count: integer read fSize write Resize;
    property Capacity: integer read fCap write Reserve;
    property Elem[index: integer]: T read GetElem write SetElem; default;

    function ToString: string; override;
    begin
      Result := '';
      for var i := 0 to fSize - 1 do
        Result += fData[i].ToString + ' '; 
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  SimpleSet<T> = class 
  private 
    data: DynArray<T>;
  public 
    constructor Create;
    begin
      data := new DynArray<T>;
    end;

    procedure Add(x: T);
    begin
      if data.Find(x) = -1 then 
        data.Add(x);
    end;

    procedure Remove(x: T);
    begin
      var xPos := data.Find(x);
      if xPos <> -1 then
        data.Remove(xPos);
    end;

    function Contains(x: T): boolean;
    begin
      Result := (data.Find(x) <> -1);
    end;

    function ToString: string; override;
    begin
      Result := data.ToString;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;

type
  AssocArray<KeyType, ValueType> = class
  private 
    keys: DynArray<KeyType>;
    values: DynArray<ValueType>;

    procedure SetElem(key: KeyType; value: ValueType);
    begin
      var ind := Keys.Find(key);
      if ind <> -1 then
        Values[ind] := value
      else
      begin
        Keys.Add(key);
        Values.Add(value);
      end;
    end;

    function GetElem(key: KeyType): ValueType;
    begin
      var ind := Keys.Find(key);
      if ind <> -1 then
        Result := Values[ind]
      else Result := default(ValueType);
    end;

  public 
    constructor Create;
    begin
      keys := new DynArray<KeyType>;
      values := new DynArray<ValueType>;
    end;

    property Elem[key: KeyType]: ValueType read GetElem write SetElem; default;

    function ToString: string; override;
    const
      NewLine = #13#10;
    begin
      Result := '';
      for var i := 0 to keys.Count - 1 do
        Result += keys[i].ToString + ' ' + values[i].ToString + NewLine;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      write(ToString);
    end;
  end;

