type
  LinkedList<T> = class
  private 
    fFirst: LinkedListNode<T>;
    fLast: LinkedListNode<T>;
  public 
    constructor Create;
    begin
    end;

    property First: LinkedListNode<T> read fFirst;
    property Last: LinkedListNode<T> read fLast;

    procedure AddFirst(x: T);
    begin
      var val := new LinkedListNode<T>(x, nil, fFirst);
      if fFirst <> nil then
        fFirst.fPrev := val;

      fFirst := val;
      if fLast = nil then
        fLast := fFirst;
    end;

    procedure AddLast(x: T);
    begin
      var val := new LinkedListNode<T>(x, fLast, nil);
      if fLast <> nil then
        fLast.fNext := val;

      fLast := val;
      if fFirst = nil then
        fFirst := fLast;
    end;

    procedure RemoveFirst();
    begin
      if fFirst = nil then
        raise new Exception('Attempt to remove from empty list');

      fFirst := fFirst.fNext;
      if fFirst = nil then
        fLast := nil
      else
        fFirst.fPrev := nil;
    end;

    procedure RemoveLast();
    begin
      if fLast = nil then
        raise new Exception('Attempt to remove from empty list');

      fLast := fLast.fPrev;
      if fLast = nil then
        fFirst := nil
      else
        fLast.fNext := nil;
    end;

    procedure AddBefore(node: LinkedListNode<T>; x: T);
    begin
      if node = nil then
        raise new Exception('Parameter node is null reference');

      if node = fFirst then
        AddFirst(x)
      else
      begin
        var val := new LinkedListNode<T>(x, node.fPrev, node);
        node.fPrev.fNext := val;
        node.fPrev := val;
      end;
    end;

    procedure AddAfter(node: LinkedListNode<T>; x: T);
    begin
      if node = nil then
        raise new Exception('Parameter node is null reference');

      if node = fLast then
        AddLast(x)
      else
      begin
        var val := new LinkedListNode<T>(x, node, node.fNext);
        node.fNext.fPrev := val;
        node.fNext := val;
      end;
    end;

    procedure Remove(node: LinkedListNode<T>);
    begin
      if node = nil then
        raise new Exception('Parameter node is null reference');

      if node = fFirst then
        RemoveFirst
      else if node = fLast then
        RemoveLast
      else
      begin
        node.fPrev.fNext := node.fNext;
        node.fNext.fPrev := node.fPrev;
      end;
    end;

    function ToString: string; override;
    begin
      Result := '';
      var cur := fFirst;
      while cur <> nil do
      begin
        Result := cur.Value.ToString + ' ';
        cur := cur.Next;
      end;
    end;

    procedure Print;
    begin
      write(ToString);
    end;

    procedure Println;
    begin
      writeln(ToString);
    end;
  end;
